CREATE OR REPLACE FUNCTION farm_v2_bank.post_coin(p_user uuid, p_request text, p_amount integer, p_direction text, p_reason text, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE w farm_v2_bank.wallets; e farm_v2_bank.ledger;
BEGIN
 IF p_user IS NULL OR p_request IS NULL OR p_request !~ '^[A-Za-z0-9._:-]{1,120}$' OR p_amount IS NULL OR p_amount<=0
 OR p_direction IS NULL OR p_direction NOT IN ('credit','debit') OR p_reference IS NULL OR p_reason IS NULL
 OR NOT ((p_direction='debit' AND p_reason IN ('farm_seed_purchase','farm_pot_synthesis','farm_decor_purchase','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase','farm_v2_land_unlock'))
 OR (p_direction='credit' AND p_reason IN ('farm_crop_exchange','farm_mission_reward'))) THEN
 RAISE EXCEPTION 'INVALID_FARM_WALLET_OPERATION'; END IF;
 INSERT INTO farm_v2_bank.wallets(user_id) VALUES(p_user) ON CONFLICT DO NOTHING;
 SELECT * INTO w FROM farm_v2_bank.wallets WHERE user_id=p_user FOR UPDATE;
 SELECT * INTO e FROM farm_v2_bank.ledger WHERE user_id=p_user AND request_key='op:'||p_request;
 IF FOUND THEN
  IF (e.amount,e.direction,e.reason,e.reference) IS DISTINCT FROM (p_amount,p_direction,p_reason,p_reference) THEN RAISE EXCEPTION 'FARM_WALLET_INTENT_MISMATCH'; END IF;
  RETURN jsonb_build_object('id',e.id,'duplicate',true,'coins',w.balance);
 END IF;
 IF p_direction='debit' AND w.balance<p_amount THEN RAISE EXCEPTION 'FARM_COIN_INSUFFICIENT'; END IF;
 UPDATE farm_v2_bank.wallets SET balance=balance+CASE WHEN p_direction='credit' THEN p_amount ELSE -p_amount END,updated_at=now() WHERE user_id=p_user RETURNING * INTO w;
 INSERT INTO farm_v2_bank.ledger(user_id,request_key,amount,direction,reason,reference) VALUES(p_user,'op:'||p_request,p_amount,p_direction,p_reason,p_reference) RETURNING * INTO e;
 RETURN jsonb_build_object('id',e.id,'duplicate',false,'coins',w.balance);
END; $function$

CREATE OR REPLACE FUNCTION public.core_wallet_apply_transaction(p_owner_id uuid, p_amount integer, p_currency text, p_direction text, p_idempotency_key text, p_reason text, p_reference_id text, p_reference_type text, p_reversal_of uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_wallet public.core_wallets;
  v_entry public.core_wallet_ledger;
  v_balance integer;
  v_sign integer;
  v_free integer := 0;
  v_paid integer := 0;
begin
  if p_owner_id is null or p_amount <= 0 or p_currency not in ('coin','crystal','destiny_ticket')
    or p_direction not in ('credit','debit') or btrim(p_idempotency_key) = '' then
    raise exception 'Invalid core wallet transaction';
  end if;

  perform public.core_wallet_get_or_create(p_owner_id);

  select * into v_entry from public.core_wallet_ledger
   where owner_id = p_owner_id and idempotency_key = p_idempotency_key;
  if found then
    if v_entry.amount <> p_amount or v_entry.currency <> p_currency or v_entry.direction <> p_direction
      or v_entry.reason <> p_reason or v_entry.reference_id <> p_reference_id
      or v_entry.reference_type <> p_reference_type then
      return jsonb_build_object('result_status','duplicate_conflict');
    end if;
    select * into v_wallet from public.core_wallets where owner_id = p_owner_id;
    return jsonb_build_object('result_status','duplicate',
      'wallet', public.core_wallet_get_or_create(p_owner_id), 'transaction', to_jsonb(v_entry));
  end if;

  select * into v_wallet from public.core_wallets where owner_id = p_owner_id for update;
  v_sign := case when p_direction = 'credit' then 1 else -1 end;
  v_balance := case p_currency
    when 'coin' then v_wallet.coin_balance
    when 'crystal' then v_wallet.crystal_balance
    else v_wallet.destiny_ticket_balance end;

  if p_direction = 'debit' and v_balance < p_amount then
    return jsonb_build_object('result_status','insufficient_funds');
  end if;

  if p_currency = 'crystal' then
    if p_direction = 'credit' then
      if public.core_crystal_credit_pool(p_reason, p_reference_type) = 'paid' then
        v_paid := p_amount;
      else
        v_free := p_amount;
      end if;
    else
      -- Free crystals are always spent before paid crystals.
      v_free := least(v_wallet.free_crystal_balance, p_amount);
      v_paid := p_amount - v_free;
    end if;
  end if;

  update public.core_wallets set
    coin_balance = coin_balance
      + case when p_currency = 'coin' then v_sign * p_amount else 0 end,
    crystal_balance = crystal_balance
      + case when p_currency = 'crystal' then v_sign * p_amount else 0 end,
    free_crystal_balance = free_crystal_balance + v_sign * v_free,
    paid_crystal_balance = paid_crystal_balance + v_sign * v_paid,
    destiny_ticket_balance = destiny_ticket_balance
      + case when p_currency = 'destiny_ticket' then v_sign * p_amount else 0 end,
    updated_at = now()
  where id = v_wallet.id
  returning * into v_wallet;

  insert into public.core_wallet_ledger(
    wallet_id, owner_id, amount, currency, direction, idempotency_key, reason,
    reference_id, reference_type, reversal_of, free_crystal_amount, paid_crystal_amount
  ) values (
    v_wallet.id, p_owner_id, p_amount, p_currency, p_direction, p_idempotency_key, p_reason,
    p_reference_id, p_reference_type, p_reversal_of, v_free, v_paid
  ) returning * into v_entry;

  return jsonb_build_object('result_status','created',
    'wallet', public.core_wallet_get_or_create(p_owner_id), 'transaction', to_jsonb(v_entry));
end; $function$

CREATE OR REPLACE FUNCTION public.farm_v2_apply_atomic_pot_wallet(p_operation_id uuid, p_owner_id uuid, p_request_id text, p_command jsonb, p_reference_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_contract jsonb;v_net integer;v_result jsonb;v_transaction uuid;v_grade integer;
BEGIN
 IF p_owner_id IS NULL OR p_operation_id IS NULL OR p_request_id IS NULL OR p_request_id !~ '^[A-Za-z0-9._:-]{1,120}$'
 OR p_command IS NULL OR jsonb_typeof(p_command)<>'object' OR p_command->>'kind' IS DISTINCT FROM 'synthesize'
 OR coalesce(p_command->>'species','') !~ '^[1-6]$' OR jsonb_typeof(p_command->'useDisplayed') IS DISTINCT FROM 'boolean'
 OR (SELECT count(*) FROM jsonb_object_keys(p_command))<>4 THEN RAISE EXCEPTION 'INVALID_ATOMIC_POT_COMMAND'; END IF;
 v_grade:=array_position(ARRAY['黃','玄','地','天','仙','神'],p_command->>'grade')-1;
 IF v_grade IS NULL OR p_reference_id IS NULL OR p_reference_id !~ '^[1-6]:[0-5]:[01]$'
 OR split_part(p_reference_id,':',1)<>p_command->>'species' OR split_part(p_reference_id,':',2)<>v_grade::text THEN RAISE EXCEPTION 'INVALID_ATOMIC_POT_COMMAND'; END IF;
 -- A fresh permit created by the real platform HTTP bridge must be visible
 -- here. A separate Farm DB/clone cannot satisfy this co-location check.
 PERFORM 1 FROM auth.users WHERE id=p_owner_id FOR SHARE;
 PERFORM 1 FROM core.users WHERE auth_user_id=p_owner_id FOR SHARE;
 PERFORM pg_advisory_xact_lock(hashtextextended('farm-v2-paid:'||p_owner_id::text,0));
 PERFORM 1 FROM public.farm_v2_paid_operations WHERE id=p_operation_id AND user_id=p_owner_id AND request_id=p_request_id AND action='POST:/farm/v2/workshop' AND state='OPEN' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FARM_ATOMIC_AUTHORITY_MISMATCH'; END IF;
 IF NOT public.farm_v2_identity_active(p_owner_id) THEN RAISE EXCEPTION 'FARM_SESSION_NOT_ACTIVE'; END IF;
 IF EXISTS(SELECT 1 FROM public.farm_v2_atomic_pot_receipts WHERE user_id=p_owner_id AND request_id=p_request_id) THEN RAISE EXCEPTION 'FARM_ATOMIC_JOURNAL_REQUIRED'; END IF;
 IF EXISTS(SELECT 1 FROM public.core_wallet_ledger WHERE owner_id=p_owner_id AND idempotency_key='farm-v2:'||p_request_id||':primary') THEN RAISE EXCEPTION 'FARM_LEGACY_WORKSHOP_RECONCILIATION_REQUIRED'; END IF;
 v_contract:=public.farm_v2_workshop_wallet_contract('farm_pot_synthesis',p_reference_id);
 v_net:=(v_contract->>'reward')::integer-(v_contract->>'cost')::integer;
 v_result:=public.farm_v2_apply_authorized_wallet_transaction(p_operation_id,p_owner_id,p_request_id,abs(v_net),'coin',CASE WHEN v_net<0 THEN 'debit' ELSE 'credit' END,'farm_pot_synthesis',p_reference_id,'farm_pot_synthesis',NULL);
 IF v_result->>'result_status'='compensated' THEN RAISE EXCEPTION 'FARM_MUTATION_COMPENSATED'; END IF;
 IF v_result->>'result_status' IS DISTINCT FROM 'created' THEN RAISE EXCEPTION '%',upper(coalesce(v_result->>'result_status','INVALID_CORE_RESULT')); END IF;
 v_transaction:=(v_result->'transaction'->>'id')::uuid;
 INSERT INTO public.farm_v2_atomic_pot_receipts(user_id,request_id,transaction_id,command) VALUES(p_owner_id,p_request_id,v_transaction,p_command);
 RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.farm_v2_apply_authorized_wallet_transaction(p_operation_id uuid, p_owner_id uuid, p_request_id text, p_amount integer, p_currency text, p_direction text, p_reason text, p_reference_id text, p_reference_type text, p_original_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('farm-v2-paid:'||p_owner_id::text,0));
 PERFORM 1 FROM public.farm_v2_paid_operations WHERE id=p_operation_id AND user_id=p_owner_id AND state='OPEN' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'FARM_AUTHORIZATION_FENCED'; END IF;
 RETURN public.farm_v2_apply_wallet_transaction(p_owner_id,p_request_id,p_amount,p_currency,p_direction,p_reason,p_reference_id,p_reference_type,p_original_transaction_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.farm_v2_apply_wallet_transaction(p_owner_id uuid, p_request_id text, p_amount integer, p_currency text, p_direction text, p_reason text, p_reference_id text, p_reference_type text, p_original_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_key text;
  v_original public.core_wallet_ledger;
  v_land integer;
  v_quantity bigint;
  v_unit integer;
  v_reward integer;
  v_result jsonb;
  v_contract jsonb;
  v_cost integer := 0;
BEGIN
  IF p_owner_id IS NULL OR p_request_id IS NULL
     OR p_request_id !~ '^[A-Za-z0-9._:-]{1,120}$'
     OR p_amount IS NULL OR p_amount <= 0 OR p_currency IS NULL
     OR p_direction IS NULL OR p_reason IS NULL
     OR p_reference_id IS NULL OR p_reference_type IS NULL THEN
    RETURN jsonb_build_object('result_status','invalid');
  END IF;
  -- Shared owner lock serializes first requests, duplicate probes, reversals,
  -- and primary retries. Core's own row lock still protects all other writers.
  PERFORM pg_advisory_xact_lock(hashtextextended('farm-v2-wallet:' || p_owner_id::text, 0));
  v_key := 'farm-v2:' || p_request_id || ':primary';
  IF p_reason<>'farm_wallet_compensation' AND EXISTS(SELECT 1 FROM public.farm_v2_wallet_closures WHERE user_id=p_owner_id AND request_id=p_request_id) THEN RETURN jsonb_build_object('result_status','compensated'); END IF;

  IF p_reason = 'farm_wallet_compensation' THEN
    SELECT * INTO v_original FROM public.core_wallet_ledger
      WHERE id=p_original_transaction_id AND owner_id=p_owner_id
        AND idempotency_key=v_key AND reversal_of IS NULL;
    IF NOT FOUND OR v_original.reason NOT IN ('farm_seed_purchase','farm_crop_exchange','farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase')
      OR p_reference_type <> 'farm_wallet_compensation' OR p_reference_id <> p_request_id
      OR p_amount <> v_original.amount OR p_currency <> v_original.currency
      OR p_direction <> (CASE v_original.direction WHEN 'debit' THEN 'credit' ELSE 'debit' END) THEN
      RETURN jsonb_build_object('result_status','invalid');
    END IF;
    v_key := 'farm-v2:' || p_request_id || ':compensation';
  ELSE
    IF p_reason IN ('farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase') THEN
      v_contract := public.farm_v2_workshop_wallet_contract(p_reason,p_reference_id);
      IF v_contract IS NULL OR p_original_transaction_id IS NOT NULL OR p_currency<>(v_contract->>'currency')
        OR p_reference_type<>p_reason OR p_amount<>abs((v_contract->>'cost')::integer-(v_contract->>'reward')::integer)
        OR p_direction<>(CASE WHEN (v_contract->>'cost')::integer>(v_contract->>'reward')::integer THEN 'debit' ELSE 'credit' END)
      THEN RETURN jsonb_build_object('result_status','invalid'); END IF;
      v_cost := (v_contract->>'cost')::integer;
    ELSE
    IF p_original_transaction_id IS NOT NULL OR p_reference_id !~ '^[1-6]:[1-9][0-9]{0,9}$' THEN
      RETURN jsonb_build_object('result_status','invalid');
    END IF;
    v_land := split_part(p_reference_id, ':', 1)::integer;
    v_quantity := split_part(p_reference_id, ':', 2)::bigint;
    IF v_quantity > 2147483647 THEN RETURN jsonb_build_object('result_status','invalid'); END IF;
    IF p_reason = 'farm_seed_purchase' THEN
      IF p_reference_type <> 'farm_seed_pack' OR p_currency <> 'coin' OR p_direction <> 'debit'
         OR v_land=6 OR p_amount <> v_quantity THEN
        RETURN jsonb_build_object('result_status','invalid');
      END IF;
    ELSIF p_reason = 'farm_crop_exchange' THEN
      v_unit := CASE v_land WHEN 1 THEN 5 WHEN 2 THEN 2 ELSE 1 END;
      v_reward := CASE v_land WHEN 4 THEN 2 WHEN 5 THEN 4 ELSE 1 END;
      IF p_reference_type <> 'farm_crop_exchange' OR p_direction <> 'credit'
        OR p_currency <> (CASE v_land WHEN 6 THEN 'crystal' ELSE 'coin' END)
        OR v_quantity % v_unit <> 0 OR p_amount::bigint <> (v_quantity / v_unit) * v_reward THEN
        RETURN jsonb_build_object('result_status','invalid');
      END IF;
    ELSE RETURN jsonb_build_object('result_status','invalid');
    END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM public.core_wallet_ledger WHERE owner_id=p_owner_id
      AND idempotency_key='farm-v2:' || p_request_id || ':compensation') THEN
      RETURN jsonb_build_object('result_status','compensated');
    END IF;
  END IF;
  -- Check lifecycle under the same row lock used by Core's balance mutation.
  -- A suspension committed while Core waits must not admit a new Farm effect.
  -- An absent row cannot be locked. Core creation must finish before checking
  -- lifecycle, including a concurrent creator committing a suspended wallet.
  PERFORM public.core_wallet_get_or_create(p_owner_id);
  PERFORM 1 FROM public.core_wallets WHERE owner_id=p_owner_id FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.core_wallets WHERE owner_id=p_owner_id AND status <> 'active') THEN
    RETURN jsonb_build_object('result_status','wallet_not_active');
  END IF;
  -- Net posting is atomic; gross cost must still be affordable before the reward.
  -- Duplicate retries bypass affordability and retain Core payload validation.
  IF v_cost>0 AND NOT EXISTS(SELECT 1 FROM public.core_wallet_ledger WHERE owner_id=p_owner_id AND idempotency_key=v_key)
     AND (SELECT CASE p_currency WHEN 'coin' THEN coin_balance ELSE crystal_balance END FROM public.core_wallets WHERE owner_id=p_owner_id)<v_cost THEN
    RETURN jsonb_build_object('result_status','insufficient_funds');
  END IF;
  v_result := public.core_wallet_apply_transaction(p_owner_id, p_amount, p_currency,
    p_direction, v_key, p_reason, p_reference_id, p_reference_type, p_original_transaction_id);
  -- Core duplicate matching does not promise reversal identity. Farm does.
  IF v_result->>'result_status' IN ('created','duplicate')
     AND v_result->'transaction'->>'reversal_of' IS DISTINCT FROM p_original_transaction_id::text THEN
    RAISE EXCEPTION 'FARM_WALLET_RESULT_CONFLICT';
  END IF;
  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.farm_v2_closed_wallet_request_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP<>'INSERT' THEN
  -- Do not change non-Farm Core/V1 writers; protect both sides of a rename.
  IF OLD.idempotency_key LIKE 'farm-v2:%' OR NEW.idempotency_key LIKE 'farm-v2:%'
   OR OLD.reason IN ('farm_seed_purchase','farm_crop_exchange','farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase','farm_wallet_compensation')
   OR NEW.reason IN ('farm_seed_purchase','farm_crop_exchange','farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase','farm_wallet_compensation')
  THEN RAISE EXCEPTION 'FARM_LEDGER_IMMUTABLE'; END IF;
  RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 END IF;
 IF NEW.reason IN ('farm_seed_purchase','farm_crop_exchange','farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase') AND EXISTS(
  SELECT 1 FROM public.farm_v2_wallet_closures c WHERE c.user_id=NEW.owner_id
  AND NEW.idempotency_key IN ('farm-v2:'||c.request_id||':primary','farm-v2:'||c.request_id||':primary:debit:coin','farm-v2:'||c.request_id||':primary:credit:coin','farm-v2:'||c.request_id||':primary:credit:crystal')
 ) THEN RAISE EXCEPTION 'FARM_MUTATION_COMPENSATED'; END IF;
 RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.farm_v2_operator_wallet_reconcile(p_user_id uuid, p_request_id text, p_mode text, p_case_id text, p_actor text, p_evidence text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_entries jsonb; v_original public.core_wallet_ledger; v_count integer; v_result jsonb; v_land integer; v_qty bigint; v_unit integer; v_reward integer;
BEGIN
 IF p_user_id IS NULL OR p_request_id IS NULL OR p_request_id !~ '^[A-Za-z0-9._:-]{1,120}$'
 OR p_mode IS NULL OR p_mode NOT IN ('inspect','compensate','cancel') OR nullif(btrim(p_case_id),'') IS NULL OR nullif(btrim(p_actor),'') IS NULL OR nullif(btrim(p_evidence),'') IS NULL THEN RAISE EXCEPTION 'INVALID_RECONCILIATION'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('farm-v2-wallet:'||p_user_id::text,0));
 SELECT count(*),coalesce(jsonb_agg(to_jsonb(l)),'[]'::jsonb) INTO v_count,v_entries FROM public.core_wallet_ledger l WHERE owner_id=p_user_id AND reversal_of IS NULL AND reason IN ('farm_seed_purchase','farm_crop_exchange','farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase')
 AND idempotency_key IN ('farm-v2:'||p_request_id||':primary','farm-v2:'||p_request_id||':primary:debit:coin','farm-v2:'||p_request_id||':primary:credit:coin','farm-v2:'||p_request_id||':primary:credit:crystal');
 IF p_mode='inspect' THEN RETURN jsonb_build_object('primary',v_entries,'compensation',(SELECT to_jsonb(l) FROM public.core_wallet_ledger l WHERE owner_id=p_user_id AND idempotency_key='farm-v2:'||p_request_id||':compensation'),'closure',(SELECT to_jsonb(c) FROM public.farm_v2_wallet_closures c WHERE user_id=p_user_id AND request_id=p_request_id)); END IF;
 IF v_count>1 OR (p_mode='cancel' AND v_count<>0) OR (p_mode='compensate' AND v_count<>1) THEN RAISE EXCEPTION 'RECONCILIATION_EVIDENCE_CONFLICT'; END IF;
 IF p_mode='cancel' THEN
  INSERT INTO public.farm_v2_wallet_closures VALUES(p_user_id,p_request_id,p_case_id,p_actor,p_evidence,'CANCELED',now()) ON CONFLICT(user_id,request_id) DO NOTHING;
  v_result:=jsonb_build_object('result_status','canceled');
 ELSE
  SELECT * INTO v_original FROM public.core_wallet_ledger WHERE id=(v_entries->0->>'id')::uuid;
  IF v_original.reason IN ('farm_pot_synthesis','farm_decor_purchase','farm_mission_reward','farm_pet_food_purchase','farm_pet_purchase','farm_formation_purchase') THEN
   v_result:=public.farm_v2_workshop_wallet_contract(v_original.reason,v_original.reference_id);
   IF v_result IS NULL OR v_original.currency<>(v_result->>'currency') OR v_original.reference_type<>v_original.reason
     OR v_original.amount<>abs((v_result->>'cost')::integer-(v_result->>'reward')::integer)
     OR v_original.direction<>(CASE WHEN (v_result->>'cost')::integer>(v_result->>'reward')::integer THEN 'debit' ELSE 'credit' END)
   THEN RAISE EXCEPTION 'RECONCILIATION_SOURCE_INVALID'; END IF;
  ELSE
  IF v_original.reference_id !~ '^[1-6]:[1-9][0-9]{0,9}$' THEN RAISE EXCEPTION 'RECONCILIATION_SOURCE_INVALID'; END IF;
  v_land:=split_part(v_original.reference_id,':',1)::integer; v_qty:=split_part(v_original.reference_id,':',2)::bigint;
  IF v_original.reason='farm_seed_purchase' THEN
   IF v_land=6 OR v_original.currency<>'coin' OR v_original.direction<>'debit' OR v_original.reference_type<>'farm_seed_pack' OR v_original.amount<>v_qty THEN RAISE EXCEPTION 'RECONCILIATION_SOURCE_INVALID'; END IF;
  ELSE
   v_unit:=CASE v_land WHEN 1 THEN 5 WHEN 2 THEN 2 ELSE 1 END; v_reward:=CASE v_land WHEN 4 THEN 2 WHEN 5 THEN 4 ELSE 1 END;
   IF v_original.direction<>'credit' OR v_original.reference_type<>'farm_crop_exchange' OR v_original.currency<>(CASE v_land WHEN 6 THEN 'crystal' ELSE 'coin' END) OR v_qty%v_unit<>0 OR v_original.amount::bigint<>(v_qty/v_unit)*v_reward THEN RAISE EXCEPTION 'RECONCILIATION_SOURCE_INVALID'; END IF;
  END IF;
  END IF;
  PERFORM 1 FROM public.core_wallets WHERE owner_id=p_user_id FOR UPDATE;
  IF EXISTS(SELECT 1 FROM public.core_wallets WHERE owner_id=p_user_id AND status<>'active') AND NOT EXISTS(SELECT 1 FROM public.core_wallet_ledger WHERE owner_id=p_user_id AND idempotency_key='farm-v2:'||p_request_id||':compensation') THEN
   v_result:=jsonb_build_object('result_status','wallet_not_active');
  ELSE
  v_result:=public.core_wallet_apply_transaction(p_user_id,v_original.amount,v_original.currency,CASE v_original.direction WHEN 'debit' THEN 'credit' ELSE 'debit' END,
    'farm-v2:'||p_request_id||':compensation','farm_wallet_compensation',p_request_id,'farm_wallet_compensation',v_original.id);
  END IF;
  IF v_result->>'result_status' IN ('created','duplicate') THEN
   IF v_result->'transaction'->>'reversal_of' IS DISTINCT FROM v_original.id::text THEN RAISE EXCEPTION 'RECONCILIATION_EVIDENCE_CONFLICT'; END IF;
   INSERT INTO public.farm_v2_wallet_closures VALUES(p_user_id,p_request_id,p_case_id,p_actor,p_evidence,'COMPENSATED',now()) ON CONFLICT(user_id,request_id) DO NOTHING;
  END IF;
 END IF;
 INSERT INTO public.farm_v2_wallet_reconciliation_audit(user_id,request_id,case_id,actor,evidence,result_status) VALUES(p_user_id,p_request_id,p_case_id,p_actor,p_evidence,v_result->>'result_status');
 RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.farm_v2_resolve_verified_wallet_owner(p_user_id text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
DECLARE v_owner uuid;
BEGIN
 BEGIN v_owner:=p_user_id::uuid; EXCEPTION WHEN invalid_text_representation THEN RETURN NULL; END;
 IF v_owner IS NULL OR p_user_id<>v_owner::text THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.farm_v2_player_state WHERE user_id=p_user_id)
 OR NOT public.farm_v2_identity_active(v_owner)
 OR NOT EXISTS(SELECT 1 FROM public.core_wallets WHERE owner_id=v_owner AND status='active')
 THEN RETURN NULL; END IF;
 RETURN v_owner;
END; $function$

CREATE OR REPLACE FUNCTION public.farm_v2_workshop_wallet_contract(p_reason text, p_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
DECLARE v_cost integer;v_reward integer;v_grade integer;v_first integer;v_currency text:='coin';
        v_from text;v_to text;v_from_cost integer;v_to_cost integer;
BEGIN
 IF p_reason='farm_pot_synthesis' AND p_reference ~ '^[1-6]:[0-5]:[01]$' THEN
  v_grade:=split_part(p_reference,':',2)::integer;v_first:=split_part(p_reference,':',3)::integer;
  v_cost:=(ARRAY[3,7,20,60,200,600])[v_grade+1];v_reward:=(ARRAY[15,30,60,90,150,300])[v_grade+1]*v_first;
 ELSIF p_reason='farm_decor_purchase' AND p_reference ~ '^DF[0-9]{3}:[01]$' THEN
  v_first:=split_part(p_reference,':',2)::integer;
  v_cost:=CASE split_part(p_reference,':',1) WHEN 'DF001' THEN 88 WHEN 'DF002' THEN 188 WHEN 'DF003' THEN 288 WHEN 'DF004' THEN 588 WHEN 'DF005' THEN 888 WHEN 'DF006' THEN 1288 WHEN 'DF007' THEN 1888 WHEN 'DF008' THEN 2888 WHEN 'DF009' THEN 3888 WHEN 'DF010' THEN 5888 WHEN 'DF011' THEN 6888 WHEN 'DF012' THEN 7888 WHEN 'DF013' THEN 8888 WHEN 'DF014' THEN 9888 WHEN 'DF015' THEN 11888 WHEN 'DF016' THEN 13888 WHEN 'DF017' THEN 15888 WHEN 'DF018' THEN 18888 ELSE NULL END;
  IF v_cost IS NULL THEN RETURN NULL; END IF;v_reward:=30*v_first;
 ELSIF p_reason='farm_mission_reward' AND p_reference ~ '^MISSION_[DW]0[1-4]:[0-9]{1,16}$' THEN
  v_cost:=0;v_reward:=CASE split_part(p_reference,':',1) WHEN 'MISSION_D01' THEN 2 WHEN 'MISSION_D02' THEN 3 WHEN 'MISSION_D03' THEN 3 WHEN 'MISSION_D04' THEN 5 WHEN 'MISSION_W01' THEN 10 WHEN 'MISSION_W02' THEN 15 WHEN 'MISSION_W03' THEN 15 WHEN 'MISSION_W04' THEN 20 END;
 ELSIF p_reason='farm_pet_food_purchase' AND p_reference ~ '^[1-9][0-9]{0,9}$' AND p_reference::bigint<=1073741823 THEN
  v_cost:=p_reference::integer*2;v_reward:=0;
 ELSIF p_reason='farm_pet_purchase' AND p_reference IN ('1','2') THEN
  v_cost:=CASE p_reference WHEN '1' THEN 300 ELSE 100 END;v_reward:=0;v_currency:=CASE p_reference WHEN '1' THEN 'coin' ELSE 'crystal' END;
 ELSIF p_reason='farm_formation_purchase' THEN
  IF p_reference='FORMATION_PREMIUM_V2' THEN
   v_cost:=388;
  ELSIF p_reference ~ '^FORMATION_PURCHASE:(FORMATION_XUANLING_188|FORMATION_JIUXIAO_288|FORMATION_PREMIUM_V2)$' THEN
   v_cost:=CASE split_part(p_reference,':',2) WHEN 'FORMATION_XUANLING_188' THEN 188 WHEN 'FORMATION_JIUXIAO_288' THEN 288 WHEN 'FORMATION_PREMIUM_V2' THEN 388 END;
  ELSIF p_reference ~ '^FORMATION_UPGRADE:(FORMATION_XUANLING_188|FORMATION_JIUXIAO_288|FORMATION_PREMIUM_V2):(FORMATION_XUANLING_188|FORMATION_JIUXIAO_288|FORMATION_PREMIUM_V2)$' THEN
   v_from:=split_part(p_reference,':',2);v_to:=split_part(p_reference,':',3);
   v_from_cost:=CASE v_from WHEN 'FORMATION_XUANLING_188' THEN 188 WHEN 'FORMATION_JIUXIAO_288' THEN 288 ELSE 388 END;
   v_to_cost:=CASE v_to WHEN 'FORMATION_XUANLING_188' THEN 188 WHEN 'FORMATION_JIUXIAO_288' THEN 288 ELSE 388 END;
   IF v_to_cost<=v_from_cost THEN RETURN NULL; END IF;
   v_cost:=v_to_cost-v_from_cost;
  ELSE
   RETURN NULL;
  END IF;
  v_reward:=0;v_currency:='crystal';
 ELSE RETURN NULL;
 END IF;
 RETURN jsonb_build_object('cost',v_cost,'reward',v_reward,'currency',v_currency);
END;
$function$
